<script setup>
import { computed, ref } from 'vue'; import { ArrowLeft, CreditCard, Eye, Pencil, XCircle } from 'lucide-vue-next'; import { useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; import { useInvoiceStore } from '@/stores/invoice'; import { usePaymentStore } from '@/stores/payment'; import { useUiStore } from '@/stores/ui'; import { useMasterDataStore } from '@/stores/masterData'; import { formatCurrency, formatDate } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import ConfirmDialog from '@/components/ui/ConfirmDialog.vue'; import PaymentModal from '@/components/payment/PaymentModal.vue';
const route=useRoute(),router=useRouter(),auth=useAuthStore(),store=useInvoiceStore(),payments=usePaymentStore(),masterData=useMasterDataStore(),ui=useUiStore(),confirm=ref(false),open=ref(false);const invoice=computed(()=>store.getInvoiceById(route.params.id));const readOnly=computed(()=>auth.role==='manager');const summary=computed(()=>payments.paymentSummaryByInvoice(invoice.value));const history=computed(()=>invoice.value?payments.paymentsByInvoice(invoice.value.id):[]);const account=(id)=>masterData.getAccountById(id);const docBadge=s=>({draft:['Draft','default'],published:['Diterbitkan','info'],cancelled:['Dibatalkan','danger']}[s]);const payBadge=s=>({belum_dibayar:['Belum Dibayar','neutral'],dibayar_sebagian:['Dibayar Sebagian','warning'],lunas:['Lunas','success'],jatuh_tempo:['Jatuh Tempo','danger']}[s]);const cancel=()=>{store.cancelInvoice(invoice.value.id);ui.notify('Invoice berhasil dibatalkan.');confirm.value=false};const saved=()=>ui.notify('Pembayaran berhasil dicatat.');
</script>
<template><div v-if="invoice" class="p-6"><header class="mb-5 flex items-start justify-between gap-4"><div class="flex gap-3"><button class="mt-0.5 rounded p-1 text-[#667085] hover:bg-[#F5F7FA]" aria-label="Kembali ke invoice" @click="router.push({name:'invoice'})"><ArrowLeft :size="18"/></button><div><div class="flex flex-wrap items-center gap-2"><h1 class="text-xl font-semibold text-[#172033]">{{invoice.number}}</h1><BaseBadge :variant="docBadge(invoice.status)[1]">{{docBadge(invoice.status)[0]}}</BaseBadge><BaseBadge :variant="payBadge(summary.status)[1]">{{payBadge(summary.status)[0]}}</BaseBadge></div><p class="mt-0.5 text-sm text-[#667085]">{{invoice.name}}</p></div></div><div class="flex flex-wrap justify-end gap-2"><BaseButton variant="secondary" @click="router.push({name:'invoice-preview',params:{id:invoice.id}})"><Eye :size="15"/>Preview</BaseButton><BaseButton v-if="!readOnly&&summary.remaining>0&&invoice.status==='published'" @click="open=true"><CreditCard :size="15"/>Catat Pembayaran</BaseButton><BaseButton v-if="!readOnly&&invoice.status!=='cancelled'" variant="secondary" @click="router.push({name:'invoice-edit',params:{id:invoice.id}})"><Pencil :size="15"/>Edit</BaseButton><BaseButton v-if="!readOnly&&invoice.status!=='cancelled'" variant="danger" @click="confirm=true"><XCircle :size="15"/>Batalkan</BaseButton></div></header><div class="grid gap-5 xl:grid-cols-3"><div class="space-y-5 xl:col-span-2"><BaseCard padding="p-5"><h2 class="mb-4 text-[15px] font-semibold text-[#172033]">Informasi Invoice</h2><dl class="grid gap-4 text-sm sm:grid-cols-3"><div><dt class="text-[#667085]">Klien</dt><dd class="mt-1 font-medium">{{invoice.client}}</dd></div><div><dt class="text-[#667085]">Tanggal Invoice</dt><dd class="mt-1 font-medium">{{formatDate(invoice.date)}}</dd></div><div><dt class="text-[#667085]">Jatuh Tempo</dt><dd class="mt-1 font-medium">{{formatDate(invoice.dueDate)}}</dd></div></dl></BaseCard><BaseCard padding="p-0"><div class="border-b border-[#E2E6EC] px-5 py-4"><h2 class="text-[15px] font-semibold">Rincian Item</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[620px]"><thead class="bg-[#F9FAFB]"><tr><th v-for="h in ['Produk / Layanan','Deskripsi','Harga','Qty','Total']" :key="h" class="px-5 py-3 text-left text-xs font-medium text-[#667085] last:text-right">{{h}}</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id" class="border-t border-[#F0F2F5]"><td class="px-5 py-3.5 text-sm font-medium">{{item.product||'-'}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{item.description}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{formatCurrency(item.price)}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{item.qty}}</td><td class="px-5 py-3.5 text-right text-sm font-medium">{{formatCurrency(item.price*item.qty)}}</td></tr></tbody></table></div></BaseCard><BaseCard padding="p-0"><div class="border-b border-[#E2E6EC] px-5 py-4"><h2 class="text-[15px] font-semibold">Riwayat Pembayaran</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[650px]"><thead class="bg-[#F9FAFB]"><tr><th v-for="h in ['Tanggal','Metode','Rekening','Referensi','Nominal']" :key="h" class="px-4 py-3 text-left text-xs font-medium text-[#667085] first:px-5 last:text-right">{{h}}</th></tr></thead><tbody><tr v-if="!history.length"><td colspan="5" class="px-5 py-8 text-center text-sm text-[#9CA3AF]">Belum ada pembayaran tercatat</td></tr><tr v-for="payment in history" :key="payment.id" class="border-t border-[#F0F2F5]"><td class="px-5 py-3 text-sm text-[#667085]">{{formatDate(payment.paymentDate)}}</td><td class="px-4 py-3 text-sm text-[#667085]">{{payment.method}}</td><td class="px-4 py-3 text-sm text-[#667085]">{{account(payment.accountId)?.nama||'-'}}</td><td class="px-4 py-3 font-mono text-xs text-[#667085]">{{payment.referenceNumber||'-'}}</td><td class="px-4 py-3 text-right text-sm font-semibold">{{formatCurrency(payment.amount)}}</td></tr></tbody></table></div></BaseCard></div><aside><BaseCard padding="p-5" class="xl:sticky xl:top-6"><h2 class="mb-4 text-[15px] font-semibold">Ringkasan Billing</h2><div class="space-y-3 text-sm"><div class="flex justify-between text-[#667085]"><span>Total Invoice</span><span class="font-medium text-[#172033]">{{formatCurrency(summary.total)}}</span></div><div class="flex justify-between text-[#667085]"><span>Total Pembayaran</span><span class="font-medium text-green-600">{{formatCurrency(summary.totalPaid)}}</span></div><div class="flex justify-between border-t border-[#E2E6EC] pt-3"><span class="font-semibold text-[#172033]">Sisa Tagihan</span><strong :class="summary.remaining?'text-[#D97706]':'text-green-600'">{{formatCurrency(summary.remaining)}}</strong></div></div></BaseCard></aside></div><ConfirmDialog :open="confirm" title="Batalkan Invoice" message="Invoice akan tetap tersimpan sebagai riwayat." confirm-label="Batalkan" danger @cancel="confirm=false" @confirm="cancel"/><PaymentModal :open="open" :invoice="invoice" @close="open=false" @saved="saved"/></div><div v-else class="p-6 text-sm text-[#667085]">Invoice tidak ditemukan.</div></template>
